// Kill-switch service worker. This file used to be auto-generated by
// vite-plugin-pwa (Workbox), which precached the entire app shell and
// served it cache-first — meaning returning users could refresh forever
// and never receive a new deploy, since the old service worker never let a
// fresh index.html/JS bundle reach the page to begin with. See
// vite.config.ts for the full story.
//
// Browsers fetch /sw.js directly (bypassing any currently-installed
// service worker's own fetch handler) whenever they check for updates, so
// this file reaches already-affected users without needing their stale,
// already-cached JS to run first. Once installed, its only job is to wipe
// every cache, unregister itself, and reload any open tab — after that, no
// service worker controls the page at all, and updates are handled purely
// by VersionChecker's polling instead.
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const cacheNames = await caches.keys();
      await Promise.all(cacheNames.map((name) => caches.delete(name)));
      await self.registration.unregister();
      const clientsList = await self.clients.matchAll({ type: 'window' });
      clientsList.forEach((client) => client.navigate(client.url));
    })()
  );
});
